        """Skip whitespace (excluding newlines unless skip_newlines=True)."""
        while self.peek() and self.peek() in (' ', '\t', '\r'):
            self.advance()
        if skip_newlines:
            while self.peek() == '\n':
                self.advance()

    def skip_comment(self) -> None:
        """Skip comment line (# to end of line)."""
        if self.peek() == '#':
